// Source is the activity_source name of Garmin Connect activity IDs.
const Source = "garmin"

// overlap re-reads recent days on every sync so renames in Garmin Connect
// and late uploads are picked up.
const overlap = 7 * 24 * time.Hour

// Setting keys of the persisted sync state.
const (
	settingLastSync  = "garmin.last_sync"
	settingLastState = "garmin.last_state"
)

// State is the persisted result of the last sync, shown in the panel.
type State struct {
	At         time.Time `json:"at"`
	OK         bool      `json:"ok"`
	Error      string    `json:"error,omitempty"`
	NeedsLogin bool      `json:"needs_login,omitempty"`
	Listed     int       `json:"listed"`
	Imported   int       `json:"imported"`
	Known      int       `json:"known"`
	NoFile     int       `json:"no_file"`
	Renamed    int       `json:"renamed"`
}

// Syncer imports new Garmin Connect activities.
type Syncer struct {
	Runner   *Runner
	Importer *importer.Importer
	Store    *store.Store
	Inbox    string
	// Since is the first day of the initial backfill.
	Since time.Time
	// Delay between downloads, to be gentle with the unofficial API.
	Delay  time.Duration
	Now    func() time.Time
	Logger *slog.Logger
}

func (s *Syncer) now() time.Time {
	if s.Now != nil {
		return s.Now()
	}
	return time.Now()
}

func (s *Syncer) logger() *slog.Logger {
	if s.Logger != nil {
		return s.Logger
	}
	return slog.New(slog.DiscardHandler)
}

// from returns the first day to list: the backfill start on the first run,
// afterwards the last successful sync minus the overlap.
func (s *Syncer) from(ctx context.Context) time.Time {
	from := s.Since
	if v, ok, err := s.Store.Setting(ctx, settingLastSync); err == nil && ok {
		if last, err := time.Parse(time.RFC3339, v); err == nil {
			if d := last.Add(-overlap); d.After(from) {
				from = d
			}
		}
	}
	return from
}

// Run lists Garmin Connect activities, downloads the unknown ones as
// original FIT files and imports them. Every imported file is reported to
// report (the panel shows them like a manual import).
func (s *Syncer) Run(ctx context.Context, report func(importer.Result)) (State, error) {
	state := State{At: s.now().UTC()}
	known, err := s.Store.SourceKeys(ctx, Source)
	if err != nil {
		return state, err
	}
	opts := SyncOptions{Since: s.from(ctx), Inbox: s.Inbox, KnownIDs: known, Delay: s.Delay}
	s.logger().Info("garmin sync started", "since", opts.Since.Format(time.DateOnly), "known", len(known))

	done, runErr := s.Runner.Sync(ctx, opts, func(ev Event) {
		if ev.Event != "activity" {
			return
		}
		switch ev.Status {
		case "downloaded":
			res := s.importFile(ctx, ev)
			if res.Status != importer.StatusFailed {
				state.Imported++
			}
			if report != nil {
				report(res)
			}
		case "known":
			state.Known++
			if changed, err := s.Store.SetSourceTitle(ctx, Source, ev.ActivityID, ev.Name); err == nil && changed {
				state.Renamed++
			}
		case "no_file":
			state.NoFile++
		}
	})
	state.Listed = done.Listed
	s.finish(ctx, &state, runErr)
	return state, runErr
}

// importFile imports one downloaded activity and links its Garmin ID.
// Inbox files are removed afterwards; the importer keeps the raw file.
func (s *Syncer) importFile(ctx context.Context, ev Event) importer.Result {
	origin := "garmin:" + ev.ActivityID
	f, err := os.Open(ev.File)
	if err != nil {
		return importer.Result{Origin: origin, Status: importer.StatusFailed, Error: err.Error()}
	}
	res := s.Importer.ImportReader(ctx, f, origin)
	f.Close()
	if res.Status == importer.StatusFailed {
		s.logger().Warn("garmin import failed", "activity", ev.ActivityID, "err", res.Error)
		return res
	}
	if err := s.Store.AttachSource(ctx, res.ActivityID, Source, ev.ActivityID, ev.Name); err != nil {
		s.logger().Warn("link garmin activity", "activity", ev.ActivityID, "err", err)
	}
	removeInbox(ev.File)
	return res
}

func removeInbox(fitPath string) {
	_ = os.Remove(fitPath)
	ext := filepath.Ext(fitPath)
	_ = os.Remove(fitPath[:len(fitPath)-len(ext)] + ".json")
}

func (s *Syncer) finish(ctx context.Context, state *State, runErr error) {
	state.OK = runErr == nil
	if runErr != nil {
		state.Error = runErr.Error()
		state.NeedsLogin = errors.Is(runErr, ErrAuthRequired)
	} else if err := s.Store.SetSetting(ctx, settingLastSync, state.At.Format(time.RFC3339)); err != nil {
		s.logger().Error("store last sync", "err", err)
	}
	b, _ := json.Marshal(state)
	if err := s.Store.SetSetting(ctx, settingLastState, string(b)); err != nil {
		s.logger().Error("store sync state", "err", err)
	}
	s.logger().Info("garmin sync finished", "ok", state.OK, "listed", state.Listed, "imported", state.Imported,
		"known", state.Known, "renamed", state.Renamed, "err", state.Error)
}

// LastState returns the result of the last sync, or nil before the first one.
func LastState(ctx context.Context, st *store.Store) (*State, error) {
	v, ok, err := st.Setting(ctx, settingLastState)
	if err != nil || !ok {
		return nil, err
	}
	var state State
	if err := json.Unmarshal([]byte(v), &state); err != nil {
		return nil, fmt.Errorf("decode sync state: %w", err)
	}
	return &state, nil
}
